const f1 = (x) => (x == null ? "—" : (+x).toFixed(1)), f2 = (x) => (x == null ? "—" : (+x).toFixed(2)), f0 = (x) => (x == null ? "—" : (+x).toFixed(0)), sg = (x, d = 1) => { if (x == null) return "—"; const a = Math.abs(x).toFixed(d); return (+a === 0 ? "" : x > 0 ? "+" : "−") + a; }, pct = (x, d = 1) => (x == null ? "—" : (x < 0 ? "−" : "") + Math.abs(+x).toFixed(d) + "%"), x3 = (x) => (x == null ? "—" : (+x).toFixed(2) + "×"), sh = (x) => (x == null ? "—" : (x * 100).toFixed(0) + "%");
const C = Object.fromEntries(S.candidates.map((c) => [c.key, c])), B = S.recommended.before, A = S.recommended.after, D = S.diagnosis, named = Object.fromEntries(S.recommended.named.map((n) => [n.d, n]));
