const NAMES = { base: "today's number", a1: "credit · a washout flips: the high-yield fund's RSI under 30 → credit adds what it would subtract", a2: "credit · no penalty in a panic: index RSI under 40 → credit may add, not subtract", a3: "credit · never subtracts", a2f: "credit · no penalty in a panic, faded in: in full at an RSI of 45, not at all at 35", b50: "depth · under the 50-day, as a third part", b100: "depth · under the 100-day, as a third part", b: "depth · the two averaged", c3: "smoother · the average of the last 3 days", c5: "smoother · the average of the last 5 days", cUp: "smoother · quick to add, slow to cut (the higher of today and the 5-day average)", d1: "top · far above the 200-day, as a third part", d2: "top · near the high and extended → tactical halved, day by day", d3: "top · near the high with RSI under 60 → tactical halved", d0: "top · near the high alone → tactical halved", d2L: "top · an extended high that holds: halved until the next washout" };
